#include <linux/fs.h>
#include <linux/sysctl.h>

int process_sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct ctl_dir *dir_hdr;
    int ret;

    dir_hdr = (struct ctl_dir *)PDE(file_inode(file)->i_private);
    if (!dir_hdr)
        return -EINVAL;

    ret = dir_emit_dots(file, ctx);
    if (ret)
        return ret;

    ret = sysctl_scan(dir_hdr, file, ctx);
    if (ret < 0)
        return ret;

    return 0;
}

int sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct sysctl_dir_header *header;
    int ret;

    header = get_sysctl_dir_header(file);
    if (!header)
        return -EFAULT;

    ret = dir_emit_dot(ctx);
    if (ret)
        return ret;

    ret = dir_emit_dotdot(ctx);
    if (ret)
        return ret;

    while (header->entries) {
        struct sysctl_entry *entry = header->entries;
        ret = scan_sysctl_entry(entry, ctx);
        if (ret)
            break;
        header->entries = entry->next;
    }

    finish_sysctl_header(header);
    return 0;
}

#include <linux/sysctl.h>
#include <linux/fs.h>

int process_sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct sysctl_dir_header *header;
    int ret;

    header = get_sysctl_dir_header(file);
    if (!header)
        return -EFAULT;

    ret = dir_emit_dot(ctx);
    if (ret < 0)
        return ret;

    ret = dir_emit_dotdot(ctx);
    if (ret < 0)
        return ret;

    while (!sysctl_dir_iter_end(header)) {
        struct sysctl_dir_entry *entry = sysctl_dir_get_next_entry(header);
        if (!entry) {
            ret = -EFAULT;
            break;
        }

        ret = scan_sysctl_dir_entry(entry, ctx);
        if (ret < 0)
            break;
    }

    finish_sysctl_dir_header(header);
    return 0;
}

int sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct sysctl_dir_header *header;

    header = sysctl_get_dir_header(file);
    if (!header)
        return -EINVAL;

    dir_emit_dot(ctx);
    dir_emit_dotdot(ctx);

    while (header->entries) {
        int err = sysctl_dir_scan(header, ctx);
        if (err)
            return err;
    }

    sysctl_finish_header(header);
    return 0;
}

#include <linux/sysctl.h>
#include <linux/fs.h>

int sysctl_dir_read(struct file *file, struct dir_context *ctx)
{
    struct sysctl_dir_header *header;
    int ret;

    header = sysctl_get_dir_header(file);
    if (!header)
        return -ENOENT;

    ret = dir_emit_dot(ctx);
    if (ret)
        return ret;

    ret = dir_emit_dotdot(ctx);
    if (ret)
        return ret;

    while (header->next_entry) {
        ret = sysctl_dir_scan(header, ctx);
        if (ret)
            break;
    }

    sysctl_finish_dir_header(header);
    return 0;
}
